// The shell.
import { app }                  from './platform.mu.js';
import { HtmlTarget }           from '@visualisation-sub/mural/visual-engine';
import { PageView, TreeView, TreeViewItem }
                                from '@visualisation-sub/mural/Controls';

// Demo modules self-register on import. Each module calls
// `register(...)` at top level — the side effect of importing
// is enough to enroll the demo with the platform's registry.
import './demos/dashboard.mjs';
import './demos/counter.mjs';
import './demos/drawer.mjs';
import './demos/tree-view.mjs';
import './demos/list-box.mjs';
import './demos/text-box.mjs';

import { allDemos, instantiateDemo } from './registry.mjs';

// Group the registered demos: { groupName: DemoDefinition[] }.
function groupDemos(defs) {
    const m = new Map();
    for (const d of defs) {
        const list = m.get(d.group);
        if (list === undefined) m.set(d.group, [d]);
        else                    list.push(d);
    }
    return m;
}

const status = document.getElementById('status');
try {
    const target = new HtmlTarget(document.getElementById('app'));
    target.Show(app.Root);

    // x:name lookups via FindName — `nav` is the empty
    // TreeView in the left strip; `page` is the PageView
    // filling the body. Both are declared in platform.mu.
    const tree = app.Root.FindName('nav');
    const page = app.Root.FindName('page');
    if (!(tree instanceof TreeView))  throw new Error('platform.mu missing x:name="nav" TreeView');
    if (!(page instanceof PageView))  throw new Error('platform.mu missing x:name="page" PageView');

    // Build the tree: one folder-style top-level TreeViewItem
    // per group, with each registered demo as a leaf child.
    // Tag carries the DemoDefinition so the selection listener
    // can recover it without a side map.
    const grouped = groupDemos(allDemos());
    for (const [groupName, defs] of grouped) {
        const group = new TreeViewItem();
        group.Header     = groupName;
        group.IsExpanded = true;
        for (const def of defs) {
            const leaf = new TreeViewItem();
            leaf.Header = def.title;
            leaf.Tag    = def;
            group.AddChild(leaf);
        }
        tree.AddChild(group);
    }

    // Activate a demo: pull its Visual from the registry cache
    // (instantiated lazily on first call) and slot it into the
    // PageView along with the title metadata.
    function activate(def) {
        const root = instantiateDemo(def.id);
        if (root === undefined) return;
        page.Title    = def.title;
        page.Subtitle = def.subtitle ?? '';
        page.Content  = root;
    }

    // Selection listener — fires whenever the user clicks a row
    // in the tree. We only react to LEAF clicks (Tag is set on
    // leaves only); clicking the group folder just selects the
    // group without activating anything.
    tree.AddSelectionChangedListener(() => {
        const item = tree.SelectedItem;
        if (item === undefined) return;
        const def = item.Tag;
        if (def === undefined || typeof def !== 'object') return;
        activate(def);
    });

    // First-load: pick the first leaf in the first group so the
    // user lands on an actual demo, not the empty welcome state.
    const firstGroup = tree.RootItems[0];
    const firstLeaf  = firstGroup?.SubItems[0];
    if (firstLeaf !== undefined) {
        tree.HandleRowClick(firstLeaf, { Shift: false, Control: false, Alt: false, Meta: false });
    }
} catch (e) {
    status.textContent = 'Error: ' + (e?.message ?? String(e));
    console.error(e);
}

import { Border, DockPanel, PageView, StackPanel, TextBlock, TreeView } from "@visualisation-sub/mural/Controls";
import { Application, Color, NameScope, Thickness } from "@visualisation-sub/mural/runtime";
import { FontWeight, SolidColorBrush } from "@visualisation-sub/mural/visual-engine";

export const app = (() => {
    const _app0 = new Application();
    const _rd1 = _app0.Resources;
    _rd1.Set("paper", new SolidColorBrush(Color.FromHex('#ffffff')));
    _rd1.Set("hairline", new SolidColorBrush(Color.FromHex('#e2e8f0')));
    _rd1.Set("primary", new SolidColorBrush(Color.FromHex('#1976d2')));
    _rd1.Set("primInk", new SolidColorBrush(Color.FromHex('#ffffff')));
    _rd1.Set("navBg", new SolidColorBrush(Color.FromHex('#f8fafc')));
    const _border2 = new Border();
    _border2.SetNameScope(new NameScope());
    _border2.set_property_value("Background", Application.current.Resources.Resolve("paper"));
    const _dockPanel3 = new DockPanel();
    const _border4 = new Border();
    _border4.set_property_value(DockPanel, "Dock", "Left");
    _border4.set_property_value("Width", 260);
    _border4.set_property_value("Background", Application.current.Resources.Resolve("navBg"));
    _border4.set_property_value("BorderBrush", Application.current.Resources.Resolve("hairline"));
    _border4.set_property_value("BorderThickness", new Thickness(0, 0, 1, 0));
    const _stackPanel5 = new StackPanel();
    const _border6 = new Border();
    _border6.set_property_value("Background", Application.current.Resources.Resolve("primary"));
    _border6.set_property_value("Padding", new Thickness(20, 16, 20, 16));
    const _textBlock7 = new TextBlock();
    _textBlock7.set_property_value("Text", "µ-mural demos");
    _textBlock7.set_property_value("FontSize", 14);
    _textBlock7.set_property_value("FontWeight", FontWeight.Bold);
    _textBlock7.set_property_value("Foreground", Application.current.Resources.Resolve("primInk"));
    _border6.SetChild(_textBlock7);
    _stackPanel5.AddChild(_border6);
    const _treeView8 = new TreeView();
    _treeView8.Name = "nav";
    _border2.nameScope.Register("nav", _treeView8);
    _treeView8.set_property_value("Indent", 18);
    _treeView8.set_property_value("Margin", new Thickness(8, 8, 8, 8));
    _stackPanel5.AddChild(_treeView8);
    _border4.SetChild(_stackPanel5);
    _dockPanel3.AddChild(_border4);
    const _pageView9 = new PageView();
    _pageView9.Name = "page";
    _border2.nameScope.Register("page", _pageView9);
    _pageView9.set_property_value("Title", "");
    _pageView9.set_property_value("Subtitle", "");
    _dockPanel3.AddChild(_pageView9);
    _border2.SetChild(_dockPanel3);
    _rd1.Root = _border2;
    return _app0;
})();

