// dashboard demo — Style + when() triggers on Border. No view-model,
// no host-side wiring; the factory just hands back the compiled root.
import { app } from '../../dashboard.mu.js';
import { register } from '../registry.mjs';

register({
    id:       'dashboard',
    group:    'Styles & Triggers',
    title:    'Dashboard',
    subtitle: 'Three Border styles with property triggers (IsMouseOver / IsPressed).',
    factory:  () => app.Root,
});

// counter demo — Button + ICommand + ComboBox. The platform factory
// builds a fresh CounterVM the first time the demo is activated and
// wires the ComboBox SelectedItem → VM.Step back-channel (mural's
// DataContextBinding is OneWay only). Subsequent activations re-use
// the same VM, so the user's counter / step survive a nav trip away
// and back.
import { app } from '../../counter.mu.js';
import { MetaData, Model, RelayCommand } from '@visualisation-sub/mural/runtime';
import { ComboBox } from '@visualisation-sub/mural/Controls';
import { register } from '../registry.mjs';

class CounterVM extends Model {
    static {
        Model.RegisterProperty(CounterVM, 'Count',     0,         MetaData.None);
        Model.RegisterProperty(CounterVM, 'Step',      1,         MetaData.None);
        Model.RegisterProperty(CounterVM, 'Steps',     undefined, MetaData.None);
        Model.RegisterProperty(CounterVM, 'Increment', undefined, MetaData.None);
        Model.RegisterProperty(CounterVM, 'Reset',     undefined, MetaData.None);
    }
    get Count()     { return this.get_property_value('Count'); }
    set Count(v)    { this.set_property_value('Count', v); }
    get Step()      { return this.get_property_value('Step'); }
    set Step(v)     { this.set_property_value('Step', v); }
    get Steps()     { return this.get_property_value('Steps'); }
    get Increment() { return this.get_property_value('Increment'); }
    get Reset()     { return this.get_property_value('Reset'); }

    constructor() {
        super();
        this.set_property_value('Steps', Object.freeze([1, 2, 5]));
        const inc = new RelayCommand(
            () => { this.Count = Math.min(10, this.Count + this.Step); },
            () => this.Count < 10,
        );
        this.set_property_value('Increment', inc);
        this.set_property_value('Reset',
            new RelayCommand(() => { this.Count = 0; }));
        this.AddPropertyChangedListener('Count', () => {
            inc.RaiseCanExecuteChanged();
        });
    }
}

function findFirstByType(visual, ctor) {
    if (visual instanceof ctor) return visual;
    for (const child of visual.visualChildren) {
        const hit = findFirstByType(child, ctor);
        if (hit !== undefined) return hit;
    }
    return undefined;
}

let initialized = false;

register({
    id:       'counter',
    group:    'Patterns',
    title:    'Counter',
    subtitle: 'Button + ICommand + ComboBox. Increment.CanExecute gates the button at 10.',
    factory: () => {
        if (!initialized) {
            const vm = new CounterVM();
            app.Root.DataContext = vm;
            // ComboBox → VM.Step back-channel. Run on a microtask so
            // the visual tree is wired before we hook AddPropertyChanged.
            queueMicrotask(() => {
                const combo = findFirstByType(app.Root, ComboBox);
                if (combo !== undefined) {
                    combo.AddPropertyChangedListener('SelectedItem', () => {
                        const v = combo.SelectedItem;
                        if (typeof v === 'number') vm.Step = v;
                    });
                }
            });
            initialized = true;
        }
        return app.Root;
    },
});

// drawer demo — Persistent left rail + Temporary right pane through
// a single DockPanel. The platform factory builds a DrawerVM on first
// activation and wires the Temporary drawer's Closed listener back
// into the VM (scrim click → VM.OptionsOpen = false).
import { app } from '../../drawer.mu.js';
import { MetaData, Model, RelayCommand } from '@visualisation-sub/mural/runtime';
import { Drawer, DrawerVariant } from '@visualisation-sub/mural/Controls';
import { register } from '../registry.mjs';

class DrawerVM extends Model {
    static {
        Model.RegisterProperty(DrawerVM, 'NavOpen',      false,     MetaData.None);
        Model.RegisterProperty(DrawerVM, 'OptionsOpen',  false,     MetaData.None);
        Model.RegisterProperty(DrawerVM, 'ToggleNav',    undefined, MetaData.None);
        Model.RegisterProperty(DrawerVM, 'OpenOptions',  undefined, MetaData.None);
        Model.RegisterProperty(DrawerVM, 'CloseOptions', undefined, MetaData.None);
    }
    get NavOpen()      { return this.get_property_value('NavOpen'); }
    set NavOpen(v)     { this.set_property_value('NavOpen', v); }
    get OptionsOpen()  { return this.get_property_value('OptionsOpen'); }
    set OptionsOpen(v) { this.set_property_value('OptionsOpen', v); }

    constructor() {
        super();
        this.set_property_value('ToggleNav',
            new RelayCommand(() => { this.NavOpen = !this.NavOpen; }));
        this.set_property_value('OpenOptions',
            new RelayCommand(() => { this.OptionsOpen = true; }));
        this.set_property_value('CloseOptions',
            new RelayCommand(() => { this.OptionsOpen = false; }));
    }
}

function findAllByType(visual, ctor, out = []) {
    if (visual instanceof ctor) out.push(visual);
    for (const child of visual.visualChildren) {
        findAllByType(child, ctor, out);
    }
    return out;
}

let initialized = false;

register({
    id:       'drawer',
    group:    'Controls',
    title:    'Drawer',
    subtitle: 'Persistent rail + Temporary overlay drawer driven from the same VM.',
    factory: () => {
        if (!initialized) {
            const vm = new DrawerVM();
            app.Root.DataContext = vm;
            queueMicrotask(() => {
                const drawers = findAllByType(app.Root, Drawer);
                for (const d of drawers) {
                    if (d.Variant === DrawerVariant.Temporary) {
                        d.AddClosedListener(() => { vm.OptionsOpen = false; });
                    }
                }
            });
            initialized = true;
        }
        return app.Root;
    },
});

// tree-view demo — composed-markup tree with multi-select. No VM
// needed; the factory just hands back the compiled root. Visual
// feedback for selection is the row highlighting itself, the standalone
// demo's external status strip lives outside the visual tree and
// doesn't translate into a platform-hosted body.
import { app } from '../../tree-view.mu.js';
import { register } from '../registry.mjs';

register({
    id:       'tree-view',
    group:    'Controls',
    title:    'TreeView',
    subtitle: 'Composed markup, chevron expand/collapse, Ctrl/Shift multi-select.',
    factory:  () => app.Root,
});

// list-box demo — declarative ListBox on the left, Items-driven on the
// right. The factory just hands back the compiled root; selection is
// already visible via row highlighting. The platform host doesn't need
// to wire a SelectionChangedListener because the demo body has no
// status strip — visual feedback IS the highlight.
import { app } from '../../list-box.mu.js';
import { register } from '../registry.mjs';

register({
    id:       'list-box',
    group:    'Controls',
    title:    'ListBox',
    subtitle: 'Declarative ListBoxItems vs. Items=[…] convenience. Extended-mode multi-select on the left (Ctrl / Shift).',
    factory:  () => app.Root,
});

// text-box demo — single-line + multi-line TextBoxes in a left-right
// split. No view-model needed; the factory hands back the compiled
// root. The runtime keyboard pipeline (HtmlTarget keydown → InputManager
// → focused TextBox) is what powers caret movement, selection, and
// clipboard — clicking inside a field focuses it, then editing works
// the same way native text inputs do.
import { app } from '../../text-box.mu.js';
import { register } from '../registry.mjs';

register({
    id:       'text-box',
    group:    'Controls',
    title:    'TextBox',
    subtitle: 'Single-line + multi-line text editing with selection, navigation, and clipboard (Ctrl+A/C/X/V).',
    factory:  () => app.Root,
});

// Lightweight in-memory registry the platform shell reads at startup.
//
// Each demo module imports `register` and calls it once at module
// top level — importing the module is enough to enroll the demo. The
// platform HTML eagerly imports every demo module so the side effect
// fires before the navigation tree is built.
//
// Demo definition shape:
//   id        — unique string, kebab-case by convention.
//   group     — section label in the navigation tree.
//   title     — shown both in the tree row and as PageView.Title.
//   subtitle  — optional, shown as PageView.Subtitle (omitted when blank).
//   factory   — `() => Visual` returning the root of the demo's tree.
//               Called the first time the demo is activated; cached for
//               subsequent activations (so state persists during the
//               session — counter values, drawer open state, etc).

const _all = [];
const _cache = new Map();   // id → instantiated root Visual

export function register(def) {
    if (def === null || typeof def !== 'object') {
        throw new Error('register(def): expected a definition object');
    }
    const { id, group, title, factory } = def;
    if (typeof id !== 'string' || id.length === 0)         throw new Error('demo def: id required');
    if (typeof group !== 'string' || group.length === 0)    throw new Error('demo def: group required');
    if (typeof title !== 'string' || title.length === 0)    throw new Error('demo def: title required');
    if (typeof factory !== 'function')                       throw new Error('demo def: factory required');
    if (_all.some(d => d.id === id)) {
        throw new Error(`demo def: '${id}' already registered`);
    }
    _all.push(def);
}

// Sorted view: group first, then title — matches how the tree renders
// them.
export function allDemos() {
    return _all.slice().sort((a, b) => {
        const g = a.group.localeCompare(b.group);
        return g !== 0 ? g : a.title.localeCompare(b.title);
    });
}

export function findDemo(id) {
    return _all.find(d => d.id === id);
}

// Materialise a demo's root Visual, caching across invocations so a
// nav-back-then-forward returns to the same state. The cache is keyed
// on definition id, not factory identity, so demos can hot-reload
// without leaking the previous tree if the factory closure ever
// changes.
export function instantiateDemo(id) {
    if (_cache.has(id)) return _cache.get(id);
    const def = findDemo(id);
    if (def === undefined) return undefined;
    const root = def.factory();
    _cache.set(id, root);
    return root;
}

// Test / debugging helper: drop the cached instance so the next
// instantiateDemo call rebuilds from scratch.
export function clearDemoCache(id) {
    if (id === undefined) _cache.clear();
    else                  _cache.delete(id);
}

// Barrel re-exports for the runtime property/binding system.
// Consumers should import from here rather than the individual files.
export { MetaData, affectsMeasure, affectsArrange, affectsRender, inherits, bindsTwoWayByDefault, } from './metadata.js';
export { PropertyDescriptor, } from './property-descriptor.js';
export { EffectiveValueDescriptor, PropertyValueSource, } from './effective-value.js';
export { Binding, BindingMode, } from './binding.js';
export { Model, PropertyKey } from './model.js';
export { Visual, Single, Panel, HorizontalAlignment, VerticalAlignment, } from './visual.js';
export { NameScope } from './namescope.js';
export { ResourceDictionary, } from './resource-dictionary.js';
export { Application } from './application.js';
export { DynamicResource } from './dynamic-resource.js';
export { DataContextBinding } from './data-context-binding.js';
export { MultiBinding } from './multi-binding.js';
export { TemplateBinding } from './template-binding.js';
export { RoutedEventArgs, PointerEventArgs, WheelEventArgs, KeyEventArgs, TextInputEventArgs, FocusEventArgs, PointerButton, NoModifiers, buildRoute, dispatchPointer, dispatchPointerDirect, dispatchKey, dispatchTextInput, dispatchFocus, } from './routed-event.js';
export { InputManager } from './input-manager.js';
export { RelayCommand, } from './command.js';
export { Style, Setter, SetterFactory, PropertyTrigger, MultiTrigger, } from './style.js';
export { isScrollInfo } from './scroll-info.js';
export { ObservableCollection, } from './observable-collection.js';
export { Point, Size, Rect, Color, Matrix, Thickness } from './primitives.js';
export { ApproximateTextMeasurer, APPROXIMATE_TEXT_MEASURER, } from './text-measurer.js';
