  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1000;
  pointer-events: none;
}

.green-dev-anchor-minimal {
  position: absolute;
  width: 70px;
  height: 40px;
  background-color: #fff;
  border-radius: 12px;
  box-shadow: 0 4px 8px rgb(0 0 0 / 20%);
  pointer-events: auto;
  z-index: 1001;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  cursor: pointer;
}

.green-dev-anchor-icon-gemini {
  width: 24px;
  height: 24px;
  background-image: var(--gemini-logo);
  background-size: cover;
  background-repeat: no-repeat;
  margin-right: 5px;
}

.green-dev-anchor-icon-open {
  width: 20px;
  height: 20px;
  background-image: var(--open-icon);
  background-size: cover;
  background-repeat: no-repeat;
}
